pub fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // If you want to enforce same-length inputs at runtime, you can uncomment the next line:
    // assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x | y)
     .collect()
}

